--
-- Database: `allfigures_db`
--

DELIMITER $$
--
-- Procedury
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `figures by cid` ()   SELECT `character`.`C_ID`, `character`.`S_ID`, `character`.`name` AS "character_name", `figure`.`name` AS "figure_name", `offer`.`link` FROM `character` left join `figure` on `figure`.`C_ID`=`character`.`C_ID` left JOIN `offer` on `offer`.`F_ID`=`figure`.`F_ID` order by `character`.`C_ID` desc$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `figures by len` ()   SELECT `character`.`C_ID`, `character`.`S_ID`, `character`.`name` AS "character_name", `figure`.`name` AS "figure_name", `offer`.`link` FROM `character` left join `figure` on `figure`.`C_ID`=`character`.`C_ID` left JOIN `offer` on `offer`.`F_ID`=`figure`.`F_ID` order by length(`character`.`name`) desc$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get all figures from C_ID` (IN `ID` INT)   SELECT `offer`.`O_ID`, 	`offer`.`price`, `offer`.`store`, `offer`.`status`, `offer`.`link`, `figure`.`name` as `figure_name`
from `offer`
JOIN `figure` on `offer`.`F_ID` = `figure`.`F_ID`
JOIN `character`on `figure`.`C_ID`=`character`.`C_ID`
WHERE `character`.`C_ID`= `ID`$$

DELIMITER ;

